/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to an Excel file. LoadWWPContext.Call(&WWPContext)
Do 'OpenDocument'
&CellRow = 1 &FirstColumn = 1
Do 'LoadGridState'
Do 'WriteFilters'
Do 'WriteColumnTitles'
Do 'WriteData'
Do 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'OpenDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&Random = Random() * 10000 &Filename = WWP_GetDefaultExportPath() + !"trnsprefeiturasWWExport-" + &Random.ToString().Trim() + !".xlsx"
&ExcelDocument.Open(&Filename) Do 'CheckStatus' &ExcelDocument.Clear()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'PREFMUNICIPIO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &PrefMunicipio1.FromString(&GridStateDynamicFilter.Value) If not &PrefMunicipio1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Municipio", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Municipio", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&PrefMunicipio1) EndIf Case &DynamicFiltersSelector1 = !'PREFNOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prefNome1.FromString(&GridStateDynamicFilter.Value) If not &prefNome1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&prefNome1) EndIf Case &DynamicFiltersSelector1 = !'PREFCNPJ' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prefCNPJ1.FromString(&GridStateDynamicFilter.Value) If not &prefCNPJ1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "CNPJ", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "CNPJ", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&prefCNPJ1) EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'PREFMUNICIPIO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &PrefMunicipio2.FromString(&GridStateDynamicFilter.Value) If not &PrefMunicipio2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Municipio", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Municipio", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&PrefMunicipio2) EndIf Case &DynamicFiltersSelector2 = !'PREFNOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prefNome2.FromString(&GridStateDynamicFilter.Value) If not &prefNome2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&prefNome2) EndIf Case &DynamicFiltersSelector2 = !'PREFCNPJ' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prefCNPJ2.FromString(&GridStateDynamicFilter.Value) If not &prefCNPJ2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "CNPJ", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "CNPJ", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&prefCNPJ2) EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'PREFMUNICIPIO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &PrefMunicipio3.FromString(&GridStateDynamicFilter.Value) If not &PrefMunicipio3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Municipio", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Municipio", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&PrefMunicipio3) EndIf Case &DynamicFiltersSelector3 = !'PREFNOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prefNome3.FromString(&GridStateDynamicFilter.Value) If not &prefNome3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&prefNome3) EndIf Case &DynamicFiltersSelector3 = !'PREFCNPJ' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prefCNPJ3.FromString(&GridStateDynamicFilter.Value) If not &prefCNPJ3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "CNPJ", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "CNPJ", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&prefCNPJ3) EndIf EndCase EndIf EndIf EndIf If not (&TFprefCodigo.IsEmpty() AND &TFprefCodigo_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Código") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFprefCodigo WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFprefCodigo_To EndIf If not (&TFprefNome_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Nome") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFprefNome_Sel) Else If not (&TFprefNome.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Nome") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFprefNome) EndIf EndIf If not (&TFprefCNPJ_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "CNPJ") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFprefCNPJ_Sel) Else If not (&TFprefCNPJ.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "CNPJ") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFprefCNPJ) EndIf EndIf If not (&TFPrefMunicipio_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Municipio") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFPrefMunicipio_Sel) Else If not (&TFPrefMunicipio.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Municipio") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFPrefMunicipio) EndIf EndIf If not (&TFprefEstado_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Estado") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFprefEstado_Sel) Else If not (&TFprefEstado.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Estado") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFprefEstado) EndIf EndIf If not (&TFprefTelefone_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Telefone") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFprefTelefone_Sel) Else If not (&TFprefTelefone.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Telefone") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFprefTelefone) EndIf EndIf If not (&TFprefContato_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Contato") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFprefContato_Sel) Else If not (&TFprefContato.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Contato") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFprefContato) EndIf EndIf If not (&TFprefStatus_Sels.Count = 0) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Situacao") &i = 1 For &TFprefStatus_Sel in &TFprefStatus_Sels If &i = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' Else &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += ', ' EndIf do Case Case &TFprefStatus_Sel.ToString().Trim() = "A" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Ativo"
Case &TFprefStatus_Sel.ToString().Trim() = "I" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Inativo"
EndCase &i += 1 EndFor EndIf &CellRow += 2
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&VisibleColumnCount = 0 If &Session.Get(!'trnsprefeiturasWWColumnsSelector') <> '' &ColumnsSelectorXML = &Session.Get(!'trnsprefeiturasWWColumnsSelector') &ColumnsSelector.FromXml(&ColumnsSelectorXML) Else Do 'InitializeColumnsSelector' EndIf
&ColumnsSelector.Columns.Sort(!'Order') For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = GetMessageText(iif(&ColumnsSelector_Column.DisplayName.IsEmpty(), &ColumnsSelector_Column.ColumnName, &ColumnsSelector_Column.DisplayName)) &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Color = 11 &VisibleColumnCount += 1 EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsprefeituras order prefCodigo when &OrderedBy = 1 AND &OrderedDsc = False order (prefCodigo) when &OrderedBy = 1 AND &OrderedDsc = True order prefNome when &OrderedBy = 2 AND &OrderedDsc = False order (prefNome) when &OrderedBy = 2 AND &OrderedDsc = True order prefCNPJ when &OrderedBy = 3 AND &OrderedDsc = False order (prefCNPJ) when &OrderedBy = 3 AND &OrderedDsc = True order PrefMunicipio when &OrderedBy = 4 AND &OrderedDsc = False order (PrefMunicipio) when &OrderedBy = 4 AND &OrderedDsc = True order prefEstado when &OrderedBy = 5 AND &OrderedDsc = False order (prefEstado) when &OrderedBy = 5 AND &OrderedDsc = True order prefTelefone when &OrderedBy = 6 AND &OrderedDsc = False order (prefTelefone) when &OrderedBy = 6 AND &OrderedDsc = True order prefContato when &OrderedBy = 7 AND &OrderedDsc = False order (prefContato) when &OrderedBy = 7 AND &OrderedDsc = True order prefStatus when &OrderedBy = 8 AND &OrderedDsc = False order (prefStatus) when &OrderedBy = 8 AND &OrderedDsc = True
using trnsprefeiturasWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &PrefMunicipio1, &prefNome1, &prefCNPJ1, &DynamicFiltersEnabled2 , &DynamicFiltersSelector2, &DynamicFiltersOperator2, &PrefMunicipio2, &prefNome2, &prefCNPJ2, &DynamicFiltersEnabled3 , &DynamicFiltersSelector3, &DynamicFiltersOperator3, &PrefMunicipio3, &prefNome3, &prefCNPJ3, &TFprefCodigo , &TFprefCodigo_To, &TFprefNome, &TFprefNome_Sel, &TFprefCNPJ, &TFprefCNPJ_Sel, &TFPrefMunicipio , &TFPrefMunicipio_Sel, &TFprefEstado, &TFprefEstado_Sel, &TFprefTelefone, &TFprefTelefone_Sel, &TFprefContato , &TFprefContato_Sel, &TFprefStatus_Sels)
// Write cell values &CellRow += 1
Do 'BeforeWriteLine' &VisibleColumnCount = 0 For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True Do Case Case &ColumnsSelector_Column.ColumnName = !'prefCodigo' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = prefCodigo Case &ColumnsSelector_Column.ColumnName = !'prefNome' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(prefNome) Case &ColumnsSelector_Column.ColumnName = !'prefCNPJ' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(prefCNPJ) Case &ColumnsSelector_Column.ColumnName = !'PrefMunicipio' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(PrefMunicipio) Case &ColumnsSelector_Column.ColumnName = !'prefEstado' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(prefEstado) Case &ColumnsSelector_Column.ColumnName = !'prefTelefone' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(prefTelefone) Case &ColumnsSelector_Column.ColumnName = !'prefContato' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(prefContato) Case &ColumnsSelector_Column.ColumnName = !'prefLogo' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = '' Case &ColumnsSelector_Column.ColumnName = !'prefStatus' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = '' do Case Case prefStatus.ToString().Trim() = "A" &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Ativo"
Case prefStatus.ToString().Trim() = "I" &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Inativo"
EndCase EndCase &VisibleColumnCount += 1 EndIf EndFor
Do 'AfterWriteLine'
Endfor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ExcelDocument.Save() Do 'CheckStatus' &ExcelDocument.Close() &Session.Set(!'WWPExportFilePath', &Filename) &Session.Set(!'WWPExportFileName', !"trnsprefeiturasWWExport.xlsx") &Filename = WWP_DownloadReport.Link()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CheckStatus'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If (&ExcelDocument.ErrCode <> 0) &Filename = "" &ErrorMessage = &ExcelDocument.ErrDescription &ExcelDocument.Close() Return EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'InitializeColumnsSelector'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ColumnsSelector = new WWPColumnsSelector() WWP_ColumnsSelector_Add(&ColumnsSelector, !"prefCodigo", '', !'Código', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"prefNome", '', !'Nome', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"prefCNPJ", '', !'CNPJ', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"PrefMunicipio", '', !'Municipio', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"prefEstado", '', !'Estado', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"prefTelefone", '', !'Telefone', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"prefContato", '', !'Contato', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"prefLogo", '', !'Logo', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"prefStatus", '', !'Situacao', True, '')
&UserCustomValue = LoadColumnsSelectorState.Udp(!'trnsprefeiturasWWColumnsSelector') If not(&UserCustomValue.IsEmpty()) &ColumnsSelectorAux.FromXml(&UserCustomValue) WWP_ColumnSelector_UpdateColumns(&ColumnsSelectorAux, &ColumnsSelector) EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsprefeiturasWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsprefeiturasWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsprefeiturasWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFPREFCODIGO" &TFprefCodigo.FromString(&GridStateFilterValue.Value) &TFprefCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFPREFNOME" &TFprefNome.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFNOME_SEL" &TFprefNome_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFCNPJ" &TFprefCNPJ.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFCNPJ_SEL" &TFprefCNPJ_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFMUNICIPIO" &TFPrefMunicipio.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFMUNICIPIO_SEL" &TFPrefMunicipio_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFESTADO" &TFprefEstado.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFESTADO_SEL" &TFprefEstado_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFTELEFONE" &TFprefTelefone.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFTELEFONE_SEL" &TFprefTelefone_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFCONTATO" &TFprefContato.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFCONTATO_SEL" &TFprefContato_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFSTATUS_SEL" &TFprefStatus_SelsJson = &GridStateFilterValue.Value &TFprefStatus_Sels.FromJson(&TFprefStatus_SelsJson) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'BeforeWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'AfterWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub

	/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */

parm(out:&Filename, out:&ErrorMessage);

